 function brush(event){if(!stroke)return;const p=point(event),last=stroke.last||p,r=Number(get('elementBrush').value),steps=Math.max(1,Math.ceil(Math.hypot(p.x-last.x,p.y-last.y)/Math.max(1,r/3)));for(let i=0;i<=steps;i++){const x=last.x+(p.x-last.x)*i/steps,y=last.y+(p.y-last.y)*i/steps;for(let ny=Math.max(0,Math.floor(y-r));ny<Math.min(canvas.height,Math.ceil(y+r));ny++)for(let nx=Math.max(0,Math.floor(x-r));nx<Math.min(canvas.width,Math.ceil(x+r));nx++)if((nx-x)**2+(ny-y)**2<=r*r)stroke.mask[ny*canvas.width+nx]=1}stroke.last=p;context.fillStyle='#168d6a66';context.beginPath();context.arc(p.x,p.y,r,0,Math.PI*2);context.fill()}
 canvas.onpointerdown=event=>{
  const p=point(event),tool=get('elementTool').value;if(tool.startsWith('smart-')){
   if(!smartReady){status('اضغط تجهيز التحديد الذكي وثبّت النموذج الاختياري إن لم يكن مثبتًا.');return}
   if(tool==='smart-box'){boxStart=p;canvas.setPointerCapture(event.pointerId)}else{if(promptPoints.length>=32){status('استخدم ٣٢ علامة كحد أقصى أو امسح النقاط.');return}promptPoints.push({...p,label:tool==='smart-positive'?1:0});paint()}return;
  }
  if(tool==='text-box'){boxStart=p;canvas.setPointerCapture(event.pointerId);return}
  if(tool==='select'){const key=current().owners[Math.max(0,Math.min(canvas.height-1,Math.floor(p.y)))*canvas.width+Math.max(0,Math.min(canvas.width-1,Math.floor(p.x)))];active=current().items.find(i=>i.key===key)?.id||null;preview=null;paint();list();return}
  if(!active){status('اختر عنصرًا معتمدًا أولًا.');return}canvas.setPointerCapture(event.pointerId);stroke={mask:new Uint8Array(canvas.width*canvas.height)};brush(event)
 };
 canvas.onpointermove=event=>{if(boxStart){paint();const p=point(event);context.strokeStyle='#285cc8';context.lineWidth=3;context.setLineDash([8,5]);context.strokeRect(boxStart.x,boxStart.y,p.x-boxStart.x,p.y-boxStart.y);context.setLineDash([])}else brush(event)};
 canvas.onpointerup=event=>{
  if(boxStart){const first=boxStart,last=point(event);boxStart=null;if(Math.abs(first.x-last.x)<3||Math.abs(first.y-last.y)<3){paint();return}const box={left:Math.min(first.x,last.x),top:Math.min(first.y,last.y),right:Math.max(first.x,last.x),bottom:Math.max(first.y,last.y)};
   if(get('elementTool').value==='text-box'){const mask=RasmEditorCore.boxInkMask(scene.engineAnalysisV2.rasterLabels,canvas.width,canvas.height,box);if(!mask.some(Boolean)){status('لا يوجد حبر داخل التحديد.');paint();return}const proposal={name:'نص وعلاماته داخل التحديد',runs:RasmEditorCore.maskRuns(mask),width:canvas.width,height:canvas.height};proposals=[proposal];preview=proposal;thumbnails();status('جُمّع الحبر داخل الإطار فقط، بلا قراءة أو إعادة كتابة. راجع ألا يقطع الإطار نقاطًا أو يضم رسمة أخرى، ثم اعتمده.')}else{promptPoints=[{x:box.left,y:box.top,label:2},{x:box.right,y:box.bottom,label:3}];status('أضف نقاطًا إذا احتجت ثم اضغط معاينة التحديد الذكي.')}paint();return;
  }
  if(!stroke)return;const mask=stroke.mask;stroke=null;mutate(()=>{const mode=get('elementTool').value;if(mode==='split')active=documentModel.split(active,mask);else documentModel.paint(active,mask,mode)})
 };
 canvas.onpointercancel=()=>{stroke=null;boxStart=null;paint()};
 get('elementApply').onclick=async()=>{if(worker)stopWorker();const target=scene,next=current().items.length?current():null,backup=Object.fromEntries(fields.map(key=>[key,target[key]]));get('elementControls').disabled=true;applying=true;applyCancelled=false;get('elementCancelJob').hidden=false;get('elementApply').disabled=true;canvas.inert=true;busy(true,'planning');status('جارٍ بناء مسار مستقل لكل عنصر…');try{await RasmImageEngine.planAsync(target,{elementDocument:next});target.elementDocument=next;await prepareColorSchedule(target);dirty=false;modal.close();refresh();queueSave();el('msg').textContent=next?'تم تطبيق '+next.items.length+' عنصر مستقل، مع حفظ الحبر غير المصنف في النهاية.':'تم الرجوع للتحليل التلقائي الأصلي دون حذف أي حبر.'}catch(error){Object.assign(target,backup);status(applyCancelled?'تم إلغاء التطبيق. المشهد السابق لم يتغير.':'لم تُطبق التعديلات: '+String(error?.message||error||'تعذّرت العملية دون تفاصيل من المتصفح.'))}finally{applying=false;get('elementCancelJob').hidden=true;busy(false);get('elementControls').disabled=false;get('elementClose').disabled=false;get('elementApply').disabled=!documentModel?.snapshot.items.length&&!scene?.elementDocument;canvas.inert=false}};
 root.renderElementTimeline=function(){let track=get('timelineElementTrack');if(!track){track=document.createElement('div');track.id='timelineElementTrack';get('timelineVideoTrack').after(track)}track.replaceChildren();let any=false;for(let index=0;index<scenes.length;index++){const s=scenes[index];if(!s.elementDocument)continue;any=true;const items=s.elementDocument.items,plans=s.enginePlanV2?.elements||[],sum=plans.reduce((n,e)=>n+(e.durationWeight??1),0),draw=sceneSeconds(s)*(1-s.hold/100);let at=offset(index);for(const plan of plans){const item=items.find(i=>i.key===plan.id),duration=draw*(plan.durationWeight??1)/sum,b=button(item?.name||'باقي الحبر',()=>{pick(index);root.openElementReview(s,item?.id)});b.className='timelineElement';b.style.left=(at*timelineScale)+'px';b.style.width=Math.max(2,duration*timelineScale)+'px';b.title=(item?.name||'باقي الحبر غير المصنف')+' · '+duration.toFixed(2)+' ث';b.dataset.elementId=item?.id||'unassigned';b.dataset.scene=index;track.append(b);at+=duration}}track.hidden=!any};
